function registerCampaignsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/pins/analytics", OpenAPI.Servers.middleware(impl, ad_pins_analytics_read, ad_pins_analytics_validate, ad_pins_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/campaigns/targeting_analytics", OpenAPI.Servers.middleware(impl, campaign_targeting_analytics_get_read, campaign_targeting_analytics_get_validate, campaign_targeting_analytics_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/campaigns/analytics", OpenAPI.Servers.middleware(impl, campaigns_analytics_read, campaigns_analytics_validate, campaigns_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/campaigns", OpenAPI.Servers.middleware(impl, campaigns_create_read, campaigns_create_validate, campaigns_create_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/campaigns/{campaign_id}", OpenAPI.Servers.middleware(impl, campaigns_get_read, campaigns_get_validate, campaigns_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/campaigns", OpenAPI.Servers.middleware(impl, campaigns_list_read, campaigns_list_validate, campaigns_list_invoke; optional_middlewares...))
    HTTP.register!(router, "PATCH", path_prefix * "/ad_accounts/{ad_account_id}/campaigns", OpenAPI.Servers.middleware(impl, campaigns_update_read, campaigns_update_validate, campaigns_update_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/campaigns/delivery_estimates", OpenAPI.Servers.middleware(impl, get_campaign_delivery_estimates_read, get_campaign_delivery_estimates_validate, get_campaign_delivery_estimates_invoke; optional_middlewares...))
    return router
end
